// exact-match lookup map: normalized name -> category
const MASTER_ITEMS_MAP = {};
MASTER_ITEMS.forEach(([name,cat])=>{ MASTER_ITEMS_MAP[name.toLowerCase().trim()] = cat; });

const STOPWORDS = new Set(["or","and","with","for","of","the","a","an","to","module","set","kit","type","size","range"]);

function normTokens(str){
  return (str||"").toLowerCase().replace(/[^a-z0-9]+/g," ").split(" ")
    .filter(t=>t.length>=2 && !STOPWORDS.has(t));
}

function matchCategoryLocal(itemName){
  const inputTokens = normTokens(itemName);
  if(inputTokens.length===0) return null;
  let best=null, bestScore=0;
  for(const [name, cat] of MASTER_ITEMS){
    const refTokens = normTokens(name);
    let score=0;
    for(const t of inputTokens){ if(refTokens.includes(t)) score++; }
    if(score>bestScore){ bestScore=score; best=cat; }
  }
  if(bestScore>=1) return best;
  return null;
}

function populateItemSuggestions(){
  const dl = document.getElementById('itemSuggestions');
  const names = MASTER_ITEMS.map(x=>x[0]).slice().sort((a,b)=>a.localeCompare(b));
  dl.innerHTML = names.map(n=>`<option value="${escapeHTML(n)}"></option>`).join('');
}

/* =========================================================
   STORAGE HELPERS — backed by Firestore (see firebase-config.js).
   Same storageGet/storageSet signatures as before, so nothing
   else in this file has to change. "shared" is ignored: every
   Firestore document is already shared across everyone hitting
   this app.
========================================================= */
async function storageGet(key, shared){
  try{
    const snap = await db.collection('atl_data').doc(key).get();
    return snap.exists ? snap.data().value : null;
  }catch(e){ console.error("Firestore get failed", e); return null; }
}
async function storageSet(key, value, shared){
  try{
    await db.collection('atl_data').doc(key).set({
      value,
      updatedAt: firebase.firestore.FieldValue.serverTimestamp()
    });
    return true;
  }catch(e){ console.error("Firestore set failed", e); return false; }
}

let inventory=[];

/* =========================================================
   INIT — no authentication gate; the app loads straight into
   the Home & Dashboard view. Inventory is kept live via a
   Firestore onSnapshot listener, so changes made by anyone
   else using the app show up here automatically.
========================================================= */
async function init(){
  document.getElementById('pdf60View').href = PDF60_DATA;
  document.getElementById('pdf60Dl').href = PDF60_DATA;
  document.getElementById('pdf90View').href = PDF90_DATA;
  document.getElementById('pdf90Dl').href = PDF90_DATA;

  populateItemSuggestions();

  db.collection('atl_data').doc('atl_inventory').onSnapshot(doc=>{
    inventory = doc.exists ? (doc.data().value || []) : [];
    renderPackageGrids();
  }, err=>{
    console.error("Firestore listener failed", err);
    showToast('Could not connect to the database');
  });

  switchTab('home');
}

/* =========================================================
   NAV
========================================================= */
const TAB_TITLES = { home:"Home & Dashboard", add:"Add Inventory" };
function switchTab(tab){
  document.querySelectorAll('.side-nav button').forEach(b=>b.classList.toggle('active', b.dataset.tab===tab));
  ['home','add'].forEach(t=>{
    document.getElementById('tab-'+t).classList.toggle('hidden', t!==tab);
  });
  document.getElementById('topbarTitle').textContent = TAB_TITLES[tab] || '';
  if(tab==='home'){ showDashboardOverview(); }
  closeSidebar();
}
function openSidebar(){
  document.getElementById('sidebar').classList.add('open');
  document.getElementById('sidebarBackdrop').classList.add('open');
}
function closeSidebar(){
  document.getElementById('sidebar').classList.remove('open');
  document.getElementById('sidebarBackdrop').classList.remove('open');
}

/* =========================================================
   PACKAGE GRIDS (home dashboard)
========================================================= */
function packageCounts(){
  const counts = {P1:0,P2:0,P3:0,P4:0};
  inventory.forEach(it=>{ counts[it.package] = (counts[it.package]||0) + Number(it.quantity||0); });
  return counts;
}
function pkgTileHTML(code, count, clickable){
  const onclick = clickable ? `onclick="openPackageDetail('${code}')"` : '';
  return `
  <button class="pkg-tile" ${onclick} style="cursor:${clickable?'pointer':'default'};">
    <div class="pkg-head"><span class="pkg-tag">${code}</span><span class="pkg-count">${count} items</span></div>
    <div class="pkg-body">
      <div class="pkg-title">${PACKAGES[code]}</div>
      <div class="pkg-holes"><span></span><span></span><span></span><span></span><span></span></div>
    </div>
  </button>`;
}
function renderPackageGrids(){
  const counts = packageCounts();
  const html = ['P1','P2','P3','P4'].map(c=>pkgTileHTML(c, counts[c], true)).join('');
  document.getElementById('dashPkgGrid').innerHTML = html;
}

/* =========================================================
   DASHBOARD DETAIL
========================================================= */
function showDashboardOverview(){
  document.getElementById('dashboardOverview').classList.remove('hidden');
  document.getElementById('dashboardDetail').classList.add('hidden');
  renderPackageGrids();
}
function openPackageDetail(code){
  document.getElementById('dashboardOverview').classList.add('hidden');
  document.getElementById('dashboardDetail').classList.remove('hidden');
  document.getElementById('detailPkgLabel').textContent = code;
  document.getElementById('detailPkgTitle').textContent = code + " — " + PACKAGES[code];
  const items = inventory.filter(it=>it.package===code);
  document.getElementById('detailPkgSub').textContent = items.length
    ? `${items.length} item type(s) logged under this package.`
    : `No items logged under this package yet.`;

  const byCat = {};
  items.forEach(it=>{
    if(!byCat[it.category]) byCat[it.category]=[];
    byCat[it.category].push(it);
  });

  const container = document.getElementById('detailCategoryList');
  if(items.length===0){
    container.innerHTML = `
      <div class="card empty-state">
        <div class="eicon">🗂️</div>
        <h4>Nothing here yet</h4>
        <p>Add items from the "Add Inventory" tab and they'll automatically show up here once categorized.</p>
      </div>`;
    return;
  }
  container.innerHTML = Object.keys(byCat).sort().map(cat=>{
    const rows = byCat[cat].map(it=>`
      <div class="cat-item-row">
        <span>${escapeHTML(it.name)}<span class="src">${it.source==='photo'?'· via photo':''}</span></span>
        <span class="qty">${it.quantity}</span>
      </div>`).join('');
    return `<div class="cat-block"><h4>${escapeHTML(cat)}</h4><div class="cat-items">${rows}</div></div>`;
  }).join('');
}

function escapeHTML(s){
  const d=document.createElement('div'); d.innerText = s==null?'':String(s); return d.innerHTML;
}

/* =========================================================
   ADD INVENTORY — MANUAL
========================================================= */
function sleep(ms){ return new Promise(res=>setTimeout(res, ms)); }

// Calls the Anthropic API with automatic retries for transient failures
// (529 overloaded, 429 rate limited, 500/502/503/504). Throws on non-transient
// errors or once retries are exhausted.
async function callClaudeWithRetry(body, opts){
  const maxRetries = (opts && opts.maxRetries) || 3;
  const onRetry = opts && opts.onRetry;
  let lastErr = null;
  for(let attempt=0; attempt<=maxRetries; attempt++){
    try{
      const resp = await fetch("https://api.anthropic.com/v1/messages", {
        method:"POST",
        headers:{"Content-Type":"application/json"},
        body: JSON.stringify(body)
      });
      let data;
      try{ data = await resp.json(); }catch(e){ data = null; }

      const errType = data && data.error && data.error.type;
      const transient = !resp.ok && (resp.status===529 || resp.status===429 || resp.status>=500 || errType==='overloaded_error' || errType==='rate_limit_error');

      if(transient){
        lastErr = new Error((data && data.error && data.error.message) || ('Server busy (status '+resp.status+')'));
        if(attempt < maxRetries){
          const delay = 900 * Math.pow(2, attempt) + Math.random()*300;
          if(onRetry) onRetry(attempt+1, maxRetries);
          await sleep(delay);
          continue;
        }
        throw lastErr;
      }

      if(!resp.ok || (data && data.error)){
        throw new Error((data && data.error && data.error.message) || ('Request failed (status '+resp.status+')'));
      }
      return data;
    }catch(networkErr){
      if(networkErr === lastErr) throw networkErr;
      lastErr = networkErr;
      if(attempt < maxRetries){
        const delay = 900 * Math.pow(2, attempt) + Math.random()*300;
        if(onRetry) onRetry(attempt+1, maxRetries);
        await sleep(delay);
        continue;
      }
      throw lastErr;
    }
  }
  throw lastErr;
}

async function classifyWithAI(itemName, onRetry){
  try{
    const data = await callClaudeWithRetry({
        model:"claude-sonnet-4-6",
        max_tokens:200,
        messages:[{role:"user", content:
          `Classify this school science-lab inventory item into exactly one category from this fixed list: ${JSON.stringify(ALL_CATEGORIES)}.\n`+
          `Item name: "${itemName}"\n`+
          `Respond ONLY with raw JSON, no markdown fences, no explanation, in this exact format: {"category":"<one of the list>"}`
        }]
      },
      { maxRetries:3, onRetry: onRetry || function(){} }
    );
    const text = (data.content||[]).map(b=>b.text||"").join("");
    const clean = text.replace(/```json|```/g,"").trim();
    const parsed = JSON.parse(clean);
    if(parsed && ALL_CATEGORIES.includes(parsed.category)) return parsed.category;
    return "Other";
  }catch(e){
    console.error("AI classify failed", e);
    return "Other";
  }
}

function setStatus(elId, type, msg){
  const el = document.getElementById(elId);
  if(!msg){ el.innerHTML=''; return; }
  const icon = type==='loading' ? '<div class="spinner"></div>' : (type==='success' ? '✅' : '⚠️');
  el.innerHTML = `<div class="status-box ${type}">${icon}<span>${msg}</span></div>`;
}

async function submitManualItem(){
  const nameEl = document.getElementById('manualItemName');
  const qtyEl = document.getElementById('manualItemQty');
  const name = nameEl.value.trim();
  const qty = parseInt(qtyEl.value,10) || 0;
  if(!name || qty<=0){ setStatus('manualStatus','error','Enter a valid item name and quantity.'); return; }

  setStatus('manualStatus','loading','Categorizing item…');

  // 1) exact match against the official catalog (selected from the dropdown)
  let category = MASTER_ITEMS_MAP[name.toLowerCase().trim()] || null;
  // 2) fuzzy match against the official catalog
  if(!category) category = matchCategoryLocal(name);
  // 3) AI fallback for anything not on the official list
  if(!category){
    category = await classifyWithAI(name, (n,max)=> setStatus('manualStatus','loading', `AI is busy — retrying (${n}/${max})…`));
  }
  const pkg = CATEGORY_TO_PACKAGE[category] || 'P4';

  inventory.push({
    id: 'it_'+Date.now()+'_'+Math.random().toString(36).slice(2,7),
    name, quantity: qty, category, package: pkg, source:'manual', dateAdded: new Date().toISOString()
  });
  await storageSet('atl_inventory', inventory, true);
  renderPackageGrids();
  setStatus('manualStatus','success', `Added "${name}" (x${qty}) → ${category} (${pkg})`);
  nameEl.value=''; qtyEl.value=1;
  showToast('Item added to inventory');
}

/* =========================================================
   TOAST
========================================================= */
let toastTimer=null;
function showToast(msg){
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(()=> t.classList.remove('show'), 2600);
}

/* Allow Enter key to submit a manual item */
document.addEventListener('keydown', function(e){
  if(e.key==='Enter'){
    if(document.activeElement && (document.activeElement.id==='manualItemName' || document.activeElement.id==='manualItemQty')){
      submitManualItem();
    }
  }
});

